// Test fixture dependency. Lives under a committed node_modules/ dir so capwall attributes
// its calls to "fixture-dep". Requires fs at load time — tests must require this module
// INSIDE the patched window (and clear the require cache between windows) so it receives
// the shimmed fs.
const fs = require("fs");
const fsPromises = require("fs/promises");
const path = require("path");

const DATA = path.join(__dirname, "data.txt");

exports.readData = () => fs.readFileSync(DATA, "utf8");
exports.readDataAsync = () => fsPromises.readFile(DATA, "utf8");
exports.writeFile = (target) => fs.writeFileSync(target, "fixture-dep was here\n");
exports.rawReadFileSync = fs.readFileSync; // for testing that uninstall/teardown behaves

// Reads DATA via the ReadStream CONSTRUCTOR (not createReadStream) — the bypass surface.
// Returns a promise of the file contents; rejects if construction is denied.
exports.readViaStreamClass = () =>
  new Promise((resolve, reject) => {
    let stream;
    try {
      stream = new fs.ReadStream(DATA);
    } catch (err) {
      reject(err);
      return;
    }
    let data = "";
    stream.on("data", (c) => (data += c));
    stream.on("end", () => resolve(data));
    stream.on("error", reject);
  });

// Existence probe — must return a boolean, never throw, even when denied.
exports.probeExists = () => fs.existsSync(DATA);

// Reads a process.env key — the anti-exfiltration surface. Attributes to "fixture-dep".
exports.readEnv = (key) => process.env[key];
// Reads via descriptor — the getOwnPropertyDescriptor exfiltration path a prior review found.
exports.readEnvDescriptor = (key) => Object.getOwnPropertyDescriptor(process.env, key);

// M4 capability surfaces, each via require() so the loader registry is exercised.
exports.connect = (host, port) => {
  const net = require("net");
  const socket = net.connect({ host, port });
  socket.on("error", () => {}); // ignore ECONNREFUSED; we only care whether the guard fired
  socket.destroy();
  return socket;
};
exports.spawn = () => require("child_process").spawnSync(process.execPath, ["-e", ""]);
exports.runVm = (code) => require("vm").runInNewContext(code);

// Class/alias egress paths a prior security review found bypassed the guard.
exports.connectViaSocketClass = (host, port) => {
  const net = require("net");
  const s = new net.Socket();
  s.on("error", () => {});
  const r = s.connect({ host, port });
  s.destroy();
  return r;
};
exports.connectViaTls = (host, port) => {
  const tls = require("tls");
  const s = tls.connect({ host, port });
  s.on("error", () => {});
  s.destroy();
  return s;
};
exports.spawnViaChildProcessClass = () => {
  const { ChildProcess } = require("child_process");
  const cp = new ChildProcess();
  return cp.spawn({ file: process.execPath, args: [process.execPath, "-e", ""] });
};
exports.sendViaDgram = (host, port) => {
  const dgram = require("dgram");
  const s = dgram.createSocket("udp4");
  s.send(Buffer.from("x"), port, host, () => s.close());
  return s;
};

// Round-2 review: class-escape / alias egress paths that defeated construct-trap guards.
exports.connectViaSocketConstructorEscape = (host, port) => {
  const s = new (require("net").Socket)();
  s.on("error", () => {});
  new (s.constructor)().connect({ host, port });
};
exports.connectViaSocketPrototype = (host, port) => {
  const net = require("net");
  const s = new net.Socket();
  s.on("error", () => {});
  net.Socket.prototype.connect.call(s, { host, port });
};
exports.spawnViaChildProcessConstructorEscape = () => {
  const { ChildProcess } = require("child_process");
  const c = new ChildProcess();
  return new (c.constructor)().spawn({ file: process.execPath, args: [process.execPath, "-e", ""] });
};
exports.connectViaHttpAgent = (host, port) => {
  const s = new (require("http").Agent)().createConnection({ host, port });
  s.on("error", () => {});
  s.destroy();
};
exports.sendViaDgramSocketClass = (host, port) => {
  const s = new (require("dgram").Socket)("udp4");
  s.send(Buffer.from("x"), port, host, () => s.close());
};
exports.tlsConnectPositional = (port, host) => {
  const s = require("tls").connect(port, host);
  s.on("error", () => {});
  s.destroy();
};
// H1: options object overrides the positional/authority target — must guard the real target.
exports.tlsConnectOverride = (port, host, overrideOpts) => {
  const s = require("tls").connect(port, host, overrideOpts);
  s.on("error", () => {});
  s.destroy();
};
exports.http2ConnectOverride = (authority, overrideOpts) => {
  const s = require("http2").connect(authority, overrideOpts);
  s.on("error", () => {});
  s.destroy();
};
// D: unbound UDP send by a granted dep — Node auto-binds + replays send; must not crash.
exports.sendUdpUnbound = (host, port, cb) => {
  const s = require("dgram").createSocket("udp4");
  s.send(Buffer.from("x"), port, host, (err) => {
    s.close();
    cb(err);
  });
};
